const cats=['home','fashion','electronics','beauty','sports'];const catProducts={home:1,fashion:4,electronics:2,beauty:7,sports:8};function url(params={}){const ids={'Form & Field':'form-field','Everyday Studio':'everyday','Northline':'northline'};if(params.store)params.store=ids[params.store]||params.store;if(params.offer)params.offer='1';return `search.html?${new URLSearchParams({lang,...params})}`}
function productCard(p){const on=saved.has(p.id),discount=p.oldPrice&&p.oldPrice>p.price?Math.round((1-p.price/p.oldPrice)*100):0;return `<article class="product-card"><div class="product-photo"><button class="product-open" data-product="${p.id}" aria-label="${e(name(p))}"><img src="${p.image}" alt="${e(name(p))}" loading="lazy"></button>${discount?`<span class="discount">−${discount}%</span>`:''}<button class="product-save" data-save="${p.id}" aria-pressed="${on}" aria-label="${t(on?'unsave':'save')}">${icon('heart')}</button></div><div class="product-info"><button class="product-name" data-product="${p.id}">${e(name(p))}</button><p class="product-price"><span>${money(p.price)}</span>${discount?`<del>${money(p.oldPrice)}</del>`:''}</p><a class="product-store" href="${url({store:p.store,scope:'products'})}">${e(p.store)}</a><p class="product-example">${t('sampleLabel')}</p></div></article>`}
